import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:yoclip_core/yoclip_core.dart';
import 'package:yoclip_encoder/yoclip_encoder.dart' as encoder_lib;

void main() {
  final outputPath = Platform.environment['YOCLIP_OUTPUT'];

  final externalImageBytes = <String, Uint8List>{
    for (final e in {"team_office":"","event":"","laptop_loft":"","corridor":"","epam_logo":"","postnl_logo":""}.entries)
      e.key: base64Decode(e.value as String),
  };

  testWidgets(
    'yoclip render mp4',
    (tester) async {
      if (outputPath == null) return;
      const projectPath = '/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip';

      final storage = LocalFileSystemStorage(projectPath);
      final project = await YoclipProject.load(storage, projectPath);

      final runtime = YoclipQuickJsRuntime();
      await runtime.init();
      addTearDown(runtime.dispose);

      final scenes = await loadYoclipProjectScenes(runtime, project, storage);

      final audioTracks = await YoclipV2AudioResolver(storage).resolveAll(
        project,
        scenes,
        externalAudioFiles: {},
      );
      final audioSpecs = await YoclipV2AudioResolver(storage).toEncoderSpecs(audioTracks);
      final encoderAudioSpecs = audioSpecs
          .map(
            (s) => encoder_lib.YoclipAudioTrackSpec(
              source: s.source,
              volume: s.volume,
              startFrame: s.startFrame,
            ),
          )
          .toList();

      final renderProject = resolveYoclipAutoDuration(project, scenes);
      final adjustedProject = YoclipProject(
        rootPath: renderProject.rootPath,
        config: YoclipProjectConfig(
          duration: renderProject.config.autoDuration
              ? renderProject.config.duration
              : 90,
          fps: 30,
          width: 1920,
          height: 1080,
          background: renderProject.config.background,
          theme: renderProject.config.theme,
          overlay: renderProject.config.overlay,
        ),
        externalAssets: renderProject.externalAssets,
        scenePaths: renderProject.scenePaths,
        pluginPaths: renderProject.pluginPaths,
        fonts: renderProject.fonts,
      );

      final renderer = YoclipV2Renderer(
        project: adjustedProject,
        scenes: scenes,
        externalFiles: {"team_office":"/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip/.yoclip_cache/external/team_office/team_office.jpg","event":"/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip/.yoclip_cache/external/event/event.jpg","laptop_loft":"/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip/.yoclip_cache/external/laptop_loft/laptop_loft.jpg","corridor":"/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip/.yoclip_cache/external/corridor/corridor.jpg","epam_logo":"/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip/.yoclip_cache/external/epam_logo/epam_logo_white.png","postnl_logo":"/Users/Uladzimir_Klyshevich/Downloads/epam_brand_book/yoclip/.yoclip_cache/external/postnl_logo/postnl_logo_white.png"},
        externalFrameDirs: {},
        externalImageBytes: externalImageBytes,
      );

      final encoder = encoder_lib.YoclipEncoderTool(
        outputPath: outputPath,
        width: 1920,
        height: 1080,
        fps: 30,
        audioTracks: encoderAudioSpecs,
      );

      await tester.runAsync(encoder.start);
      await renderer.renderToRgba(tester, (frame, rgba) async {
        await tester.runAsync(() => encoder.appendFrame(Uint8List.fromList(rgba)));
      });
      await tester.runAsync(encoder.finish);

      final outputFile = File(outputPath);
      expect(outputFile.existsSync(), isTrue);
      expect(outputFile.lengthSync(), greaterThan(1000));
    },
    skip: outputPath == null,
  );
}
